namespace sv_c47a85364e584ab483c4b1a204c59776.Services;

public enum ThemeMode
{
    Light,
    Dark,
    System
}

public sealed class ThemeState
{
    public ThemeMode Mode { get; init; } = ThemeMode.System;
    public string AccentColor { get; init; } = "#0d6efd";
}

/// <summary>
/// Scoped service — one instance per circuit, so each user/tab gets
/// independent theme state that persists across enhanced navigations.
/// </summary>
public sealed class ThemeService
{
    private ThemeState _current = new();

    public ThemeState Current => _current;

    /// <summary>
    /// Fired whenever theme or accent color changes.
    /// Subscribers call InvokeAsync(StateHasChanged) in the handler.
    /// </summary>
    public event Action? OnChange;

    public void SetTheme(ThemeMode mode)
    {
        if (_current.Mode == mode) return;
        _current = _current with { Mode = mode };
        OnChange?.Invoke();
    }

    public void SetAccentColor(string color)
    {
        if (_current.AccentColor == color) return;
        _current = _current with { AccentColor = color };
        OnChange?.Invoke();
    }

    public void Update(ThemeMode mode, string accentColor)
    {
        if (_current.Mode == mode && _current.AccentColor == accentColor) return;
        _current = new ThemeState { Mode = mode, AccentColor = accentColor };
        OnChange?.Invoke();
    }
}

@* Interactive island embedded in the static layout — reacts to theme changes in real time. *@
@rendermode InteractiveServer
@implements IDisposable
@inject ThemeService Theme

<span class="theme-indicator" title="Current theme" style="color: @Theme.Current.AccentColor;">
    @ThemeIcon @Theme.Current.Mode
</span>

@code {
    private string ThemeIcon => Theme.Current.Mode switch
    {
        ThemeMode.Dark => "🌙",
        ThemeMode.Light => "☀️",
        _ => "💻"
    };

    protected override void OnInitialized()
    {
        Theme.OnChange += HandleThemeChanged;
    }

    private void HandleThemeChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        Theme.OnChange -= HandleThemeChanged;
    }
}

@* Quick toggle — can be placed on any interactive page or in the sidebar. *@
@implements IDisposable
@inject ThemeService Theme

<div class="theme-toggle">
    <button class="btn btn-sm @ButtonClass" @onclick="CycleTheme" title="Toggle theme">
        @ThemeIcon
    </button>
</div>

@code {
    private string ThemeIcon => Theme.Current.Mode switch
    {
        ThemeMode.Dark => "🌙",
        ThemeMode.Light => "☀️",
        _ => "💻"
    };

    private string ButtonClass => Theme.Current.Mode switch
    {
        ThemeMode.Dark => "btn-dark",
        ThemeMode.Light => "btn-light",
        _ => "btn-outline-secondary"
    };

    private void CycleTheme()
    {
        var next = Theme.Current.Mode switch
        {
            ThemeMode.Light => ThemeMode.Dark,
            ThemeMode.Dark => ThemeMode.System,
            _ => ThemeMode.Light
        };
        Theme.SetTheme(next);
    }

    protected override void OnInitialized()
    {
        Theme.OnChange += HandleThemeChanged;
    }

    private void HandleThemeChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        Theme.OnChange -= HandleThemeChanged;
    }
}

@page "/settings"
@rendermode InteractiveServer
@implements IDisposable
@inject ThemeService Theme

<PageTitle>Settings</PageTitle>

<h1>User Preferences</h1>

<div class="card p-4" style="max-width: 480px;">
    <h5>Theme</h5>
    <div class="btn-group mb-3" role="group">
        @foreach (var mode in Enum.GetValues<ThemeMode>())
        {
            <button class="btn @(mode == Theme.Current.Mode ? "btn-primary" : "btn-outline-primary")"
                    @onclick="() => Theme.SetTheme(mode)">
                @mode
            </button>
        }
    </div>

    <h5>Accent Color</h5>
    <div class="d-flex align-items-center gap-2 mb-3">
        <input type="color" class="form-control form-control-color"
               value="@Theme.Current.AccentColor"
               @onchange="OnAccentChanged" />
        <span style="color: @Theme.Current.AccentColor;">@Theme.Current.AccentColor</span>
    </div>

    <h5>Preview</h5>
    <p>
        Current theme: <strong>@Theme.Current.Mode</strong> —
        Accent: <span style="color: @Theme.Current.AccentColor;">■ @Theme.Current.AccentColor</span>
    </p>
</div>

@code {
    private void OnAccentChanged(ChangeEventArgs e)
    {
        Theme.SetAccentColor(e.Value?.ToString() ?? "#0d6efd");
    }

    protected override void OnInitialized()
    {
        Theme.OnChange += HandleThemeChanged;
    }

    private void HandleThemeChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        Theme.OnChange -= HandleThemeChanged;
    }
}

