@page "/settings"
@rendermode InteractiveServer
@implements IDisposable
@inject ThemeService Theme

<PageTitle>Settings</PageTitle>

<h1>User Preferences</h1>

<div class="card p-4" style="max-width: 480px;">
    <h5>Theme</h5>
    <div class="btn-group mb-3" role="group">
        @foreach (var mode in Enum.GetValues<ThemeMode>())
        {
            <button class="btn @(mode == Theme.Current.Mode ? "btn-primary" : "btn-outline-primary")"
                    @onclick="() => Theme.SetTheme(mode)">
                @mode
            </button>
        }
    </div>

    <h5>Accent Color</h5>
    <div class="d-flex align-items-center gap-2 mb-3">
        <input type="color" class="form-control form-control-color"
               value="@Theme.Current.AccentColor"
               @onchange="OnAccentChanged" />
        <span style="color: @Theme.Current.AccentColor;">@Theme.Current.AccentColor</span>
    </div>

    <h5>Preview</h5>
    <p>
        Current theme: <strong>@Theme.Current.Mode</strong> —
        Accent: <span style="color: @Theme.Current.AccentColor;">■ @Theme.Current.AccentColor</span>
    </p>
</div>

@code {
    private void OnAccentChanged(ChangeEventArgs e)
    {
        Theme.SetAccentColor(e.Value?.ToString() ?? "#0d6efd");
    }

    protected override void OnInitialized()
    {
        Theme.OnChange += HandleThemeChanged;
    }

    private void HandleThemeChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        Theme.OnChange -= HandleThemeChanged;
    }
}

